"use client"

import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RadioGroup, RadioGroupItem } from "@atlas/ui-web/primitives/RadioGroup/RadioGroup"
import { ROLES, type OnboardingStepProps } from "../schema"

const errorStyle = {
  margin: 0,
  color: "var(--atlas-danger)",
  fontSize: "var(--atlas-font-size-sm)",
  lineHeight: "var(--atlas-line-height-snug)",
} as const

export function Profile({ data, patch, next }: OnboardingStepProps) {
  const [submitted, setSubmitted] = useState(false)

  const name = data.fullName.trim()
  const nameError = !name
    ? "Enter your full name."
    : name.length < 2
      ? "Your name must be at least 2 characters."
      : null
  const roleError = data.role ? null : "Choose the role that fits you best."

  const submit = () => {
    setSubmitted(true)
    if (nameError || roleError) return
    next()
  }

  return (
    <form
      noValidate
      onSubmit={(e) => {
        e.preventDefault()
        submit()
      }}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-6)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
      }}
    >
      <header style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h1
          style={{
            margin: 0,
            fontSize: "var(--atlas-text-h1)",
            fontWeight: "var(--atlas-font-weight-bold)",
            lineHeight: "var(--atlas-line-height-tight)",
            color: "var(--atlas-foreground)",
          }}
        >
          Tell us about you
        </h1>
        <p style={{ margin: 0, color: "var(--atlas-foreground-muted)", fontSize: "var(--atlas-font-size-sm)" }}>
          Step 1 of 3
        </p>
      </header>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <Label htmlFor="onb-name" required invalid={submitted && !!nameError}>
          Full name
        </Label>
        <Input
          id="onb-name"
          autoComplete="name"
          value={data.fullName}
          onChange={(e) => patch({ fullName: e.target.value })}
          invalid={submitted && !!nameError}
          aria-required="true"
          aria-describedby={submitted && nameError ? "onb-name-err" : undefined}
        />
        {submitted && nameError && (
          <p id="onb-name-err" role="alert" style={errorStyle}>
            {nameError}
          </p>
        )}
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <Label htmlFor="onb-role-group" required invalid={submitted && !!roleError}>
          Role
        </Label>
        <RadioGroup
          id="onb-role-group"
          aria-label="Role"
          aria-describedby={submitted && roleError ? "onb-role-err" : undefined}
          variant="card"
          size="md"
          required
          invalid={submitted && !!roleError}
          value={data.role}
          onValueChange={(role) => patch({ role })}
        >
          {ROLES.map((r) => (
            <RadioGroupItem key={r.value} value={r.value} label={r.label} variant="card" size="md" />
          ))}
        </RadioGroup>
        {submitted && roleError && (
          <p id="onb-role-err" role="alert" style={errorStyle}>
            {roleError}
          </p>
        )}
      </div>

      <Button type="submit" variant="primary" size="lg">
        Continue
      </Button>
    </form>
  )
}

